policies.inbound:


	
	
		api://bac4c929-2fd5-40ea-8e23-efafa42b2637
	
	
		https://sts.windows.net/f6d12728-e960-45d2-bf98-1421e9bc8453/
	
	
		
			Gateway.Access
		
	







<set-variable name="promptText" value="@{
	try {
		var body = context.Request.Body.As(preserveContent: true);
		var msgs = body["messages"] as JArray;
		if (msgs == null) { return ""; }
		var sb = new System.Text.StringBuilder();
		foreach (var m in msgs) { var c = m["content"]; if (c != null) { sb.Append(c.ToString()); sb.Append(" "); } }
		var t = sb.ToString();
		return t.Length > 8000 ? t.Substring(0, 8000) : t;
	} catch (Exception) { return ""; }
}" />

	
		
			@("https://cs-finops-28016.cognitiveservices.azure.com/contentsafety/text:analyze?api-version=2024-09-01")
			POST
			
				application/json
			
			@{
				var rec = new JObject(
					new JProperty("text", (string)context.Variables["promptText"]),
					new JProperty("categories", new JArray("Hate","SelfHarm","Sexual","Violence")),
					new JProperty("outputType", "FourSeverityLevels")
				);
				return rec.ToString();
			}
			
		
		<set-variable name="csBlocked" value="@{
			try {
				var r = (IResponse)context.Variables["csResp"];
				if (r == null || r.StatusCode != 200) { return "false"; }
				var b = r.Body.As(preserveContent: true);
				var arr = b["categoriesAnalysis"] as JArray;
				if (arr == null) { return "false"; }
				foreach (var c in arr) { int sev = (int?)c["severity"] ?? 0; if (sev >= 4) { return (string)c["category"]; } }
				return "false";
			} catch (Exception) { return "false"; }
		}" />
		
			
				
					
					
						application/json
					
					@{
						return new JObject(
							new JProperty("error", "content_safety_block"),
							new JProperty("message", "Prompt blocked by Azure AI Content Safety."),
							new JProperty("flaggedCategory", (string)context.Variables["csBlocked"]),
							new JProperty("requestId", context.RequestId.ToString())
						).ToString();
					}

send-request.set-body:
@{
        var roles = ((string)context.Variables["roles"] ?? "").Split(',');
        string cc = ""; string bu = "";
        foreach (var r in roles) { if (r.StartsWith("cc:")) { cc = r.Substring(3); } if (r.StartsWith("bu:")) { bu = r.Substring(3); } }
        int pt=0, ct=0, tt=0, cpt=0; string model="";
        try {
          var body = context.Response.Body.As<JObject>(preserveContent:true);
          var u = body["usage"];
          if (u != null) {
            pt = (int?)u["prompt_tokens"] ?? 0;
            ct = (int?)u["completion_tokens"] ?? 0;
            tt = (int?)u["total_tokens"] ?? 0;
            if (u["prompt_tokens_details"] != null) { cpt = (int?)u["prompt_tokens_details"]["cached_tokens"] ?? 0; }
          }
          if (body["model"] != null) { model = (string)body["model"]; }
        } catch (Exception) {}
        string deployment = context.Request.MatchedParameters.GetValueOrDefault("deployment","");
        if (string.IsNullOrEmpty(model)) { model = deployment; }
        int sc = context.Response.StatusCode;
        var rec = new JObject(
          new JProperty("TimeGenerated", DateTime.UtcNow.ToString("o")),
          new JProperty("RequestId", context.RequestId.ToString()),
          new JProperty("OperationId", context.Operation.Id),
          new JProperty("ApiName", context.Api.Name),
          new JProperty("ApiId", context.Api.Id),
          new JProperty("OperationName", context.Operation.Name),
          new JProperty("ProductName", context.Product != null ? context.Product.Name : ""),
          new JProperty("SubscriptionName", context.Subscription != null ? context.Subscription.Name : ""),
          new JProperty("RouteClass", "model"),
          new JProperty("ModelName", deployment),
          new JProperty("ModelVersion", "2025-04-14"),
          new JProperty("BackendId", context.Request.Url.Host),
          new JProperty("DeploymentRegion", "eastus2"),
          new JProperty("StatusCode", sc),
          new JProperty("IsError", sc >= 400),
          new JProperty("ErrorReason", sc >= 400 ? ("http_" + sc) : ""),
          new JProperty("TotalLatencyMs", context.Elapsed.TotalMilliseconds),
          new JProperty("BackendLatencyMs", context.Response.Headers.ContainsKey("x-ms-apim-backend-time") ? 0.0 : context.Elapsed.TotalMilliseconds),
          new JProperty("PromptTokens", pt),
          new JProperty("CompletionTokens", ct),
          new JProperty("TotalTokens", tt),
          new JProperty("CachedPromptTokens", cpt),
          new JProperty("IsStreaming", false),
          new JProperty("TokenSource", tt > 0 ? "response_body" : "none"),
          new JProperty("ClientId", (string)context.Variables["appid"]),
          new JProperty("Appid", (string)context.Variables["appid"]),
          new JProperty("Oid", (string)context.Variables["oid"]),
          new JProperty("UpnOrAppName", (string)context.Variables["appid"]),
          new JProperty("TenantIdClaim", (string)context.Variables["tid"]),
          new JProperty("BusinessUnitClaim", bu),
          new JProperty("CostCenterClaim", cc),
          new JProperty("RequestBytes", 0),
          new JProperty("ResponseBytes", 0),
          new JProperty("PolicyVersion", "v1")
        );
        return new JArray(rec).ToString();
      }
